head.b:skin:
/* Reset & Blogger Override */
body, html { margin:0; padding:0; width:100%; height:100%; overflow:hidden; background-color:#090a0f; color:#f3f4f6; font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
.glassmorphism { background: rgba(18, 22, 34, 0.75); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.08); }
.glass-btn { background: rgba(255, 255, 255, 0.08); backdrop-filter: blur(8px); transition: all 0.2s ease; }
.glass-btn:hover { background: rgba(255, 255, 255, 0.16); transform: scale(1.05); }
.neon-glow-tt { filter: drop-shadow(0 0 12px rgba(37, 244, 238, 0.3)); }
.neon-glow-yt { filter: drop-shadow(0 0 12px rgba(255, 0, 0, 0.3)); }
.neon-glow-fb { filter: drop-shadow(0 0 12px rgba(24, 119, 242, 0.3)); }

head.script:
tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        brand: {
          tiktok: '#00f2fe',
          fb: '#1877f2',
          yt: '#ff0000',
          accent: '#8b5cf6',
          dark: '#090a0f',
          surface: '#11141e'
        }
      }
    }
  }
}

import { initializeApp } from "https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js";
import { getAuth, GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged } from "https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js";
import { 
  getFirestore, collection, getDocs, addDoc, doc, setDoc, query, orderBy, limit, serverTimestamp 
} from "https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js";

const firebaseConfig = {
  apiKey: "AIzaSyA_kXYP-sW2XTNjoP5SaZ-3GuzWdZTW3lA",
  authDomain: "user-management-portals.firebaseapp.com",
  projectId: "user-management-portals",
  storageBucket: "user-management-portals.firebasestorage.app",
  messagingSenderId: "905852708317",
  appId: "1:905852708317:web:34869edc8960a30c4a4234",
  measurementId: "G-CR71FDSW6C"
};

const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbxHqGFzo4SnVma3QYzwhHLYsZXMmdF25Z15rKOoyJdkw1GmLc7Sjh9rXdkqWaoV0SiY/exec";

const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);
const provider = new GoogleAuthProvider();

window.FirebaseModule = {
  auth,
  db,
  provider,
  signInWithPopup,
  signOut,
  onAuthStateChanged,
  collection,
  getDocs,
  addDoc,
  doc,
  setDoc,
  query,
  orderBy,
  limit,
  serverTimestamp,
  GAS_WEB_APP_URL
};

// Emit event when Firebase module is ready
window.dispatchEvent(new CustomEvent('firebase-ready'));

body.script:
    window.addEventListener('firebase-ready', () => {
      initApp();
    });

    // Fallback if firebase already ready
    if (window.FirebaseModule) {
      initApp();
    }

    function initApp() {
      const { 
        auth, db, provider, signInWithPopup, signOut, onAuthStateChanged,
        collection, getDocs, addDoc, doc, setDoc, query, orderBy, limit, serverTimestamp,
        GAS_WEB_APP_URL 
      } = window.FirebaseModule;

      // Seed fallback videos covering TikTok, Facebook, YouTube
      const SEED_VIDEOS = [
        {
          id: "seed_tt_1",
          platform: "TIKTOK",
          title: "Exploring night market street food in Saigon #vietnam #streetfood",
          author: "saigon_foodie",
          avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80",
          thumbnail: "https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=600&auto=format&fit=crop&q=80",
          streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4",
          originalUrl: "https://www.tiktok.com",
          likes: 3420,
          comments: 124,
          fetchedAt: Date.now()
        },
        {
          id: "seed_yt_1",
          platform: "YOUTUBE",
          title: "Incredible FPV drone flight through ancient ruins #cinematic #fpv",
          author: "AeroVision Labs",
          avatar: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&auto=format&fit=crop&q=80",
          thumbnail: "https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=600&auto=format&fit=crop&q=80",
          streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4",
          originalUrl: "https://youtube.com/shorts",
          likes: 8520,
          comments: 412,
          fetchedAt: Date.now()
        },
        {
          id: "seed_fb_1",
          platform: "FACEBOOK",
          title: "Mastering coastal sunrise photography with mobile camera #reels #photography",
          author: "Lens & Horizons",
          avatar: "https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=100&auto=format&fit=crop&q=80",
          thumbnail: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600&auto=format&fit=crop&q=80",
          streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4",
          originalUrl: "https://facebook.com/reel",
          likes: 2190,
          comments: 89,
          fetchedAt: Date.now()
        },
        {
          id: "seed_tt_2",
          platform: "TIKTOK",
          title: "Speed coding a modern glassmorphic dashboard in 60 seconds #webdev",
          author: "dev_craft",
          avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&auto=format&fit=crop&q=80",
          thumbnail: "https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=600&auto=format&fit=crop&q=80",
          streamUrl: "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyBlazes.mp4",
          originalUrl: "https://www.tiktok.com",
          likes: 5410,
          comments: 290,
          fetchedAt: Date.now()
        }
      ];

      // App state
      const state = {
        currentUser: null,
        videos: [],
        filteredVideos: [],
        currentFilter: 'ALL',
        searchQuery: '',
        isMuted: true,
        activeVideoId: null,
        likedVideos: new Set(),
        bookmarkedVideos: new Set(),
        currentCommentVideoId: null,
        commentsCache: {}
      };

      // Expose to window
      window.shortsApp = {
        state,

        setFilter(platform) {
          state.currentFilter = platform;
          document.querySelectorAll('.filter-btn').forEach(btn => {
            if (btn.dataset.platform === platform) {
              btn.classList.add('bg-white/10', 'text-white', 'border-white/10');
              btn.classList.remove('text-gray-300');
            } else {
              btn.classList.remove('bg-white/10', 'text-white', 'border-white/10');
              btn.classList.add('text-gray-300');
            }
          });
          applyFiltersAndRender();
        },

        handleSearch(query) {
          state.searchQuery = (query || '').toLowerCase().trim();
          applyFiltersAndRender();
        },

        toggleGlobalMute() {
          state.isMuted = !state.isMuted;
          const icon = document.getElementById('muteIcon');
          if (state.isMuted) {
            icon.setAttribute('data-lucide', 'volume-x');
          } else {
            icon.setAttribute('data-lucide', 'volume-2');
          }
          lucide.createIcons();

          // Sync with all video elements
          document.querySelectorAll('#feedContainer video').forEach(v => {
            v.muted = state.isMuted;
          });
        },

        handleAuthAction() {
          if (state.currentUser) {
            signOut(auth).then(() => {
              state.currentUser = null;
              updateAuthUI();
            });
          } else {
            signInWithPopup(auth, provider).then(res => {
              state.currentUser = res.user;
              updateAuthUI();
            }).catch(err => {
              console.error("Auth error: ", err);
            });
          }
        },

        toggleLike(vidId) {
          const vid = state.videos.find(v => v.id === vidId);
          if (!vid) return;

          const likeBtn = document.querySelector(`[data-like-btn="${vidId}"]`);
          const likeCount = document.querySelector(`[data-like-count="${vidId}"]`);

          if (state.likedVideos.has(vidId)) {
            state.likedVideos.delete(vidId);
            vid.likes = Math.max(0, vid.likes - 1);
            if (likeBtn) likeBtn.classList.remove('text-rose-500', 'scale-125');
          } else {
            state.likedVideos.add(vidId);
            vid.likes = (vid.likes || 0) + 1;
            if (likeBtn) likeBtn.classList.add('text-rose-500', 'scale-125');
          }
          if (likeCount) likeCount.textContent = formatCount(vid.likes);

          // Sync to Firestore if user logged in
          if (state.currentUser) {
            setDoc(doc(db, "shorts_feed", vidId), { likes: vid.likes }, { merge: true }).catch(() => {});
          }
        },

        toggleBookmark(vidId) {
          const btn = document.querySelector(`[data-bookmark-btn="${vidId}"]`);
          if (state.bookmarkedVideos.has(vidId)) {
            state.bookmarkedVideos.delete(vidId);
            if (btn) btn.classList.remove('text-amber-400', 'scale-125');
          } else {
            state.bookmarkedVideos.add(vidId);
            if (btn) btn.classList.add('text-amber-400', 'scale-125');
          }
        },

        openComments(vidId) {
          state.currentCommentVideoId = vidId;
          const vid = state.videos.find(v => v.id === vidId);
          document.getElementById('drawerCommentCount').textContent = `(${vid ? (vid.comments || 0) : 0})`;
          document.getElementById('commentsDrawer').classList.remove('hidden');
          renderComments(vidId);
        },

        closeComments() {
          document.getElementById('commentsDrawer').classList.add('hidden');
          state.currentCommentVideoId = null;
        },

        postComment() {
          const input = document.getElementById('drawerCommentInput');
          const text = (input.value || '').trim();
          if (!text || !state.currentCommentVideoId) return;

          const author = state.currentUser ? (state.currentUser.displayName || "User") : "Anonymous";
          const newComment = {
            id: 'cmt_' + Date.now(),
            author,
            text,
            time: 'Just now'
          };

          if (!state.commentsCache[state.currentCommentVideoId]) {
            state.commentsCache[state.currentCommentVideoId] = [];
          }
          state.commentsCache[state.currentCommentVideoId].unshift(newComment);

          // Update video comment count
          const vid = state.videos.find(v => v.id === state.currentCommentVideoId);
          if (vid) {
            vid.comments = (vid.comments || 0) + 1;
            const countEl = document.querySelector(`[data-comment-count="${vid.id}"]`);
            if (countEl) countEl.textContent = formatCount(vid.comments);
            document.getElementById('drawerCommentCount').textContent = `(${vid.comments})`;
          }

          input.value = '';
          renderComments(state.currentCommentVideoId);

          if (state.currentUser) {
            addDoc(collection(db, "video_comments"), {
              videoId: state.currentCommentVideoId,
              userId: state.currentUser.uid,
              userName: author,
              text,
              createdAt: serverTimestamp()
            }).catch(() => {});
          }
        },

        shareVideo(url) {
          if (navigator.share) {
            navigator.share({ title: 'Social Ports Video', url: url || window.location.href });
          } else {
            navigator.clipboard.writeText(url || window.location.href).then(() => {
              alert('Link copied to clipboard!');
            });
          }
        },

        openModal() {
          document.getElementById('modalErrorMsg').classList.add('hidden');
          document.getElementById('modalUrlInput').value = '';
          document.getElementById('addVideoModal').classList.remove('hidden');
        },

        closeModal() {
          document.getElementById('addVideoModal').classList.add('hidden');
        },

        async submitUrlFromModal() {
          const url = (document.getElementById('modalUrlInput').value || '').trim();
          const errEl = document.getElementById('modalErrorMsg');
          const btn = document.getElementById('modalSubmitBtn');

          if (!url) {
            errEl.textContent = 'Please enter a valid video URL.';
            errEl.classList.remove('hidden');
            return;
          }

          btn.disabled = true;
          btn.innerHTML = `
Extracting...`;

          try {
            const videoObj = await extractUrlViaGAS(url);
            if (videoObj) {
              await saveVideoToFirestore(videoObj);
              state.videos.unshift(videoObj);
              applyFiltersAndRender();
              this.closeModal();
            } else {
              errEl.textContent = 'Failed to extract video details. Check link or API.';
              errEl.classList.remove('hidden');
            }
          } catch (e) {
            errEl.textContent = e.message || 'Error communicating with backend.';
            errEl.classList.remove('hidden');
          } finally {
            btn.disabled = false;
            btn.innerHTML = `Extract & Save to Feed`;
            lucide.createIcons();
          }
        },

        async quickExtract() {
          const input = document.getElementById('quickUrlInput');
          const url = (input.value || '').trim();
          const btn = document.getElementById('quickExtractBtn');

          if (!url) return;

          btn.disabled = true;
          btn.innerHTML = `
`;

          try {
            const videoObj = await extractUrlViaGAS(url);
            if (videoObj) {
              await saveVideoToFirestore(videoObj);
              state.videos.unshift(videoObj);
              applyFiltersAndRender();
              input.value = '';
              alert('Video successfully extracted and added to feed!');
            } else {
              alert('Extraction returned no video data.');
            }
          } catch (e) {
            alert('Extraction failed: ' + e.message);
          } finally {
            btn.disabled = false;
            btn.innerHTML = `Extract & Post`;
            lucide.createIcons();
          }
        }
      };

      // Listen for Auth changes
      onAuthStateChanged(auth, user => {
        state.currentUser = user;
        updateAuthUI();
      });

      function updateAuthUI() {
        const nameEl = document.getElementById('authUserName');
        const avatarEl = document.getElementById('authUserAvatar');
        const iconEl = document.getElementById('authActionIcon');
        const mobileIcon = document.getElementById('mobileAuthIcon');

        if (state.currentUser) {
          nameEl.textContent = state.currentUser.displayName || "User";
          if (state.currentUser.photoURL) {
            avatarEl.innerHTML = ``;
          }
          iconEl.setAttribute('data-lucide', 'log-out');
          mobileIcon.setAttribute('data-lucide', 'log-out');
        } else {
          nameEl.textContent = "Guest User";
          avatarEl.innerHTML = ``;
          iconEl.setAttribute('data-lucide', 'log-in');
          mobileIcon.setAttribute('data-lucide', 'user');
        }
        lucide.createIcons();
      }

      function formatCount(num) {
        if (!num) return '0';
        if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
        if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
        return num.toString();
      }

      function updateStats() {
        const tt = state.videos.filter(v => v.platform === 'TIKTOK').length;
        const fb = state.videos.filter(v => v.platform === 'FACEBOOK').length;
        const yt = state.videos.filter(v => v.platform === 'YOUTUBE').length;

        document.getElementById('statTT').textContent = tt;
        document.getElementById('statFB').textContent = fb;
        document.getElementById('statYT').textContent = yt;

        document.getElementById('badgeCountAll').textContent = state.videos.length;
        document.getElementById('badgeCountTT').textContent = tt;
        document.getElementById('badgeCountFB').textContent = fb;
        document.getElementById('badgeCountYT').textContent = yt;
      }

      function applyFiltersAndRender() {
        let list = [...state.videos];

        // Platform filter
        if (state.currentFilter !== 'ALL') {
          list = list.filter(v => v.platform === state.currentFilter);
        }

        // Search query
        if (state.searchQuery) {
          list = list.filter(v => 
            (v.title && v.title.toLowerCase().includes(state.searchQuery)) ||
            (v.author && v.author.toLowerCase().includes(state.searchQuery))
          );
        }

        state.filteredVideos = list;
        renderFeed(list);
        updateStats();
      }

      function renderFeed(videos) {
        const container = document.getElementById('feedContainer');
        container.innerHTML = '';

        if (!videos || videos.length === 0) {
          container.innerHTML = `




No short videos found

Try switching filters or add a new video URL.

          `;
          lucide.createIcons();
          return;
        }

        videos.forEach((video, index) => {
          const card = document.createElement('div');
          card.className = 'w-full h-full snap-start snap-always relative flex items-center justify-center bg-black overflow-hidden select-none';
          card.id = `card_${video.id}`;
          card.dataset.videoId = video.id;
          card.dataset.index = index;

          let badgeColor = 'bg-cyan-500/20 text-cyan-400 border-cyan-500/40 neon-glow-tt';
          let badgeLabel = 'TIKTOK';
          if (video.platform === 'FACEBOOK') {
            badgeColor = 'bg-blue-600/20 text-blue-400 border-blue-500/40 neon-glow-fb';
            badgeLabel = 'FACEBOOK';
          } else if (video.platform === 'YOUTUBE') {
            badgeColor = 'bg-red-600/20 text-red-400 border-red-500/40 neon-glow-yt';
            badgeLabel = 'YOUTUBE';
          }

          card.innerHTML = `











              ${badgeLabel}











                    @${video.author || 'creator'}


                  ${new Date(video.fetchedAt || Date.now()).toLocaleDateString()}





                ${video.title || ''}












                ${formatCount(video.likes)}








                ${formatCount(video.comments)}























          `;

          container.appendChild(card);
        });

        lucide.createIcons();
        setupIntersectionObserver();
      }

      function renderComments(vidId) {
        const listEl = document.getElementById('drawerCommentsList');
        const comments = state.commentsCache[vidId] || [
          { author: "Alex Chen", text: "This is super satisfying to watch 🔥", time: "2h ago" },
          { author: "Elena", text: "What camera was used for this shot?", time: "4h ago" }
        ];

        listEl.innerHTML = '';
        comments.forEach(c => {
          const item = document.createElement('div');
          item.className = 'p-3 rounded-xl bg-white/5 border border-white/5 flex flex-col gap-1';
          item.innerHTML = `


              @${c.author}
              ${c.time}


${c.text}
          `;
          listEl.appendChild(item);
        });
      }

      /**
       * DOM Virtualization & Playback Observer
       */
      let feedObserver = null;
      function setupIntersectionObserver() {
        if (feedObserver) {
          feedObserver.disconnect();
        }

        const options = {
          root: document.getElementById('feedContainer'),
          threshold: 0.7
        };

        feedObserver = new IntersectionObserver((entries) => {
          entries.forEach(entry => {
            const card = entry.target;
            const wrapper = card.querySelector('.video-wrapper');
            const streamUrl = wrapper.dataset.stream;
            const poster = wrapper.querySelector('.video-poster');

            if (entry.isIntersecting) {
              state.activeVideoId = card.dataset.videoId;

              // Check if video element exists, otherwise create it
              let videoEl = wrapper.querySelector('video');
              if (!videoEl && streamUrl) {
                videoEl = document.createElement('video');
                videoEl.className = 'w-full h-full object-cover relative z-10';
                videoEl.setAttribute('referrerpolicy', 'no-referrer');
                videoEl.setAttribute('playsinline', '');
                videoEl.setAttribute('webkit-playsinline', '');
                videoEl.loop = true;
                videoEl.muted = state.isMuted;
                videoEl.src = streamUrl;

                videoEl.addEventListener('loadeddata', () => {
                  if (poster) poster.style.opacity = '0';
                });

                // Tap to play / pause toggle
                videoEl.addEventListener('click', () => {
                  if (videoEl.paused) videoEl.play();
                  else videoEl.pause();
                });

                wrapper.appendChild(videoEl);
              }

              if (videoEl) {
                videoEl.muted = state.isMuted;
                const playPromise = videoEl.play();
                if (playPromise !== undefined) {
                  playPromise.catch(err => {
                    console.log("Autoplay paused by browser policy:", err);
                  });
                }
              }
            } else {
              // Pause and purge out-of-view videos to release memory
              const videoEl = wrapper.querySelector('video');
              if (videoEl) {
                videoEl.pause();
                videoEl.removeAttribute('src');
                videoEl.load();
                videoEl.remove();
                if (poster) poster.style.opacity = '1';
              }
            }
          });
        }, options);

        document.querySelectorAll('#feedContainer > div[id^="card_"]').forEach(el => {
          feedObserver.observe(el);
        });
      }

      /**
       * Smart Cache Flow with Firestore & GAS
       */
      async function loadFeedWithSmartCache() {
        let feedData = [];

        try {
          // 1. Check Firestore collection 'shorts_feed'
          const feedCol = collection(db, "shorts_feed");
          const q = query(feedCol, orderBy("fetchedAt", "desc"), limit(25));
          const snapshot = await getDocs(q);

          if (!snapshot.empty) {
            snapshot.forEach(docSnap => {
              feedData.push({ id: docSnap.id, ...docSnap.data() });
            });
          }

          // Check age of most recent document
          const newest = feedData[0];
          const isStale = !newest || (Date.now() - (newest.fetchedAt || 0) > 7200000); // 2 hours

          if (isStale) {
            console.log("Feed cache empty or older than 2h. Fetching from GAS Backend...");
            const gasResults = await fetchUnifiedFeedFromGAS();
            if (gasResults && gasResults.length > 0) {
              feedData = gasResults;
              // Batch write into Firestore
              gasResults.forEach(item => {
                setDoc(doc(db, "shorts_feed", item.id), item).catch(() => {});
              });
            }
          }
        } catch (e) {
          console.warn("Firestore fetch error, falling back to seed data:", e);
        }

        // Out of the box fallback seed data if still empty
        if (!feedData || feedData.length === 0) {
          feedData = SEED_VIDEOS;
        }

        state.videos = feedData;
        applyFiltersAndRender();
      }

      async function fetchUnifiedFeedFromGAS() {
        try {
          const res = await fetch(GAS_WEB_APP_URL, {
            method: "POST",
            headers: { "Content-Type": "text/plain;charset=utf-8" },
            body: JSON.stringify({ action: "GET_UNIFIED_FEED", region: "VN" })
          });
          const json = await res.json();
          if (json.status === "success" && json.data) {
            return json.data;
          }
        } catch (err) {
          console.error("GAS feed error: ", err);
        }
        return null;
      }

      async function extractUrlViaGAS(url) {
        const res = await fetch(GAS_WEB_APP_URL, {
          method: "POST",
          headers: { "Content-Type": "text/plain;charset=utf-8" },
          body: JSON.stringify({ action: "EXTRACT_URL", url: url })
        });
        const json = await res.json();
        if (json.status === "success" && json.data) {
          return json.data;
        } else {
          throw new Error(json.message || "Failed to extract");
        }
      }

      async function saveVideoToFirestore(video) {
        try {
          await setDoc(doc(db, "shorts_feed", video.id), video);
        } catch (e) {
          console.error("Error saving video to firestore:", e);
        }
      }

      // Initial feed load
      loadFeedWithSmartCache();
    }
